use super::*;
use crate::observe_retirement_allocations as observe;
struct Payload {text:String}
struct PayloadCursor {text:Option<String>}
impl RetireOwned for Payload{
 fn retirement(self)->Box<dyn RetirementCursor>{Box::new(PayloadCursor{text:Some(self.text)})}
 fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<PayloadCursor>())}
 fn controlled_retirement_supported()->bool{true}
}
impl RetirementCursor for PayloadCursor{
 fn next_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:if self.text.is_some(){size_of::<Option<String>>()}else{0},release_bytes:self.text.as_ref().map_or(0,String::capacity),depth:usize::from(self.text.is_some()),..Default::default()})}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetirementStep{let d=self.next_demand(g.maximum_copy_bytes).unwrap();if !crate::retained_clone::retained_clone_grant_admits(g,d){return RetirementStep::BudgetExhausted;}drop(self.text.take());RetirementStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()})}
 fn terminal_is_empty(&self)->bool{self.text.is_none()}
 fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(size_of::<Self>())}
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn step(cursor:&mut dyn RetirementCursor,g:RetainedCloneGrant)->(RetirementStep,(usize,usize)){
 for axis in 0..5{let mut denied=g;let positive=match axis{0=>{denied.maximum_items=0;true},1=>{denied.maximum_copy_bytes=g.maximum_copy_bytes.saturating_sub(1);g.maximum_copy_bytes>0},2=>{denied.maximum_capacity_bytes=g.maximum_capacity_bytes.saturating_sub(1);g.maximum_capacity_bytes>0},3=>{denied.maximum_release_bytes=g.maximum_release_bytes.saturating_sub(1);g.maximum_release_bytes>0},_=>{denied.maximum_depth=g.maximum_depth.saturating_sub(1);g.maximum_depth>0}};if positive{let(result,heap)=observe(||cursor.close_step(denied));assert!(matches!(result,RetirementStep::BudgetExhausted|RetirementStep::Progress(RetainedCloneProgress{copied_items:0,copied_bytes:0,retained_capacity_bytes:0,released_bytes:0})));assert_eq!(heap,(0,0));}}
 observe(||cursor.close_step(g))
}
/// 🚚️ Last original aliases preserve exact native payload custody on the caller frontier without nested cleanup queues.
#[test]
fn original_sealed_owned_payload_hands_native_child_to_caller_frontier(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){if row["aliases"].as_u64().unwrap()==0{assert_eq!(row["expectedChildHandoffs"],0);assert_eq!(row["expectedNativePayloadFrames"],0);continue;}let((source,text_bytes),mut total)=observe(||{let text=row["text"].as_str().unwrap().to_owned();let bytes=text.capacity();let g=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:SealedShared::<Payload>::birth_bytes(),maximum_depth:1,..Default::default()};(SealedShared::admit(Payload{text},SharedIssuer::owned(),g).unwrap_or_else(|_|panic!("original payload birth")).0,bytes)});let identity=source.identity();let mut aliases=Vec::new();for _ in 1..row["aliases"].as_u64().unwrap(){aliases.push(source.try_duplicate(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:size_of::<SealedShared<Payload>>(),maximum_depth:1,..Default::default()}).unwrap().0);}aliases.push(source);let mut handoffs=0;
 for alias in aliases{assert_eq!(alias.identity(),identity);let birth=alias.retirement_birth_bytes().unwrap();let(mut cursor,heap)=observe(||alias.retirement());assert_eq!(heap,(birth,0));total.0+=heap.0;
 let d=cursor.next_demand(4096).unwrap();let g=grant(d);let(result,heap)=step(&mut*cursor,g);let RetirementStep::Progress(p)=result else{panic!("original strong alias turn requires physical receipt")};assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(p.fits(g));total.0+=heap.0;total.1+=heap.1;
 if !cursor.terminal_is_empty(){let d=cursor.next_demand(4096).unwrap();assert_eq!(d.capacity_bytes,size_of::<PayloadCursor>(),"original typed cursor birth excludes an extra owned wrapper and nested frontier");let g=grant(d);let(result,heap)=step(&mut*cursor,g);let RetirementStep::ChildProgress(mut child,p)=result else{panic!("original typed payload must transfer its native child to caller frontier")};handoffs+=1;assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(p.fits(g));total.0+=heap.0;total.1+=heap.1;let g=grant(child.next_demand(4096).unwrap());let(result,heap)=step(&mut*child,g);let RetirementStep::Progress(p)=result else{panic!("native payload original physical close")};assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.released_bytes,text_bytes);total.0+=heap.0;total.1+=heap.1;assert!(child.terminal_is_empty());let release=child.terminal_release_bytes().unwrap();let(_,heap)=observe(||drop(child));assert_eq!(heap,(0,release));total.1+=heap.1;}
 assert!(cursor.terminal_is_empty());let release=cursor.terminal_release_bytes().unwrap();let(_,heap)=observe(||drop(cursor));assert_eq!(heap,(0,release));total.1+=heap.1;}
 assert_eq!(handoffs,row["expectedChildHandoffs"].as_u64().unwrap());assert_eq!(total.0,total.1);eprintln!("[DEBUG] original sealed native handoffs={handoffs} nestedQueues=0 physicalBirth={} physicalRelease={}",total.0,total.1);
 }
}

struct AdmissionPayload<const SUPPORTED:bool,const KNOWN:bool>(Payload);
impl<const S:bool,const K:bool> RetireOwned for AdmissionPayload<S,K>{fn retirement(self)->Box<dyn RetirementCursor>{assert!(S&&K,"unsupported native issuer must never consume its original");Box::new(PayloadCursor{text:Some(self.0.text)})}fn retirement_birth_bytes(&self)->Option<usize>{K.then_some(size_of::<PayloadCursor>())}fn controlled_retirement_supported()->bool{S}}
fn admission_case<const S:bool,const K:bool>(row:&serde_json::Value){let(mut original,mut total)=observe(||Some(AdmissionPayload::<S,K>(Payload{text:"exact original native child".to_owned()})));let pointer=original.as_ref().unwrap().0.text.as_ptr();let issuer=SharedIssuer::owned();let(quote,heap)=observe(||(issuer.demand)(original.as_ref().unwrap(),OriginalDemand::Native));assert_eq!(heap,(0,0));assert_eq!(quote.is_ok(),S&&K);let native=size_of::<PayloadCursor>();let g=RetainedCloneGrant{maximum_items:row["items"].as_u64().unwrap()as usize,maximum_capacity_bytes:if row["capacity"]=="short"{native-1}else{native},maximum_depth:row["depth"].as_u64().unwrap()as usize,..Default::default()};let(result,heap)=observe(||(issuer.admit)(OriginalSlot::Native(&mut original),g));assert_eq!(result.is_ok(),row["accepted"].as_bool().unwrap());if let Ok(Some((mut child,p)))=result{assert!(original.is_none());assert!(p.fits(g));assert_eq!(heap,(native,0));assert_eq!(p.retained_capacity_bytes,native);total.0+=heap.0;let g=grant(child.next_demand(4096).unwrap());let(result,heap)=step(&mut*child,g);let RetirementStep::Progress(p)=result else{panic!("admitted native original child close")};assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));total.0+=heap.0;total.1+=heap.1;assert!(child.terminal_is_empty());let release=child.terminal_release_bytes().unwrap();let(_,heap)=observe(||drop(child));assert_eq!(heap,(0,release));total.1+=heap.1;}else{assert_eq!(heap,(0,0));assert_eq!(original.as_ref().unwrap().0.text.as_ptr(),pointer);let(_,heap)=observe(||drop(original));assert_eq!(heap.0,0);total.1+=heap.1;}assert_eq!(total.0,total.1);}
#[test]
fn original_native_child_admission_retains_unfunded_or_unsupported_originals(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in fixture["admission"].as_array().unwrap(){match(row["supported"].as_bool().unwrap(),row["birthKnown"].as_bool().unwrap()){(true,true)=>admission_case::<true,true>(row),(false,true)=>admission_case::<false,true>(row),(true,false)=>admission_case::<true,false>(row),(false,false)=>unreachable!()}}}

struct RefusingSharedPayload(u64);
static SHARED_HOOK_PANICS:std::sync::atomic::AtomicBool=std::sync::atomic::AtomicBool::new(false);
impl RetireOwned for RefusingSharedPayload{
 fn retirement(self)->Box<dyn RetirementCursor>{retirement::leaf(self.0)}
 fn retirement_birth_bytes(&self)->Option<usize>{Some(retirement::leaf_birth_bytes::<u64>())}
 fn controlled_retirement_supported()->bool{true}
 fn shared_original_birth_bytes(&self)->Option<usize>{Some(1)}
 fn shared_original_retirement(_original:&mut Option<SharedOriginal<Self>>,_grant:RetainedCloneGrant)->Result<Option<(Box<dyn RetirementCursor>,RetainedCloneProgress)>,ValueError>{if SHARED_HOOK_PANICS.load(Ordering::SeqCst){panic!("original constructor failure")}Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"original constructor refused"))}
}
#[test]
fn shared_original_constructor_error_and_unwind_preserve_the_initialized_allocation(){
 for panics in[false,true]{let source=SealedShared::admit(RefusingSharedPayload(42),SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:SealedShared::<RefusingSharedPayload>::birth_bytes(),maximum_depth:1,..Default::default()}).unwrap_or_else(|_|panic!("shared constructor fixture birth")).0;let pointer=source.identity();let mut cursor=Cursor{handle:source,pending:ManuallyDrop::new(None),original:None};let d=cursor.demands(4096).unwrap();assert_eq!(d.capacity_bytes,1);let g=grant(d);let(result,heap)=observe(||cursor.step(RetainedCloneGrant{maximum_capacity_bytes:0,..g}));assert!(matches!(result.unwrap(),RetirementStep::BudgetExhausted));assert_eq!(heap,(0,0));assert_eq!(cursor.handle.identity(),pointer);SHARED_HOOK_PANICS.store(panics,Ordering::SeqCst);let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||cursor.step(g)));SHARED_HOOK_PANICS.store(false,Ordering::SeqCst);if panics{assert!(result.is_err())}else{match result.unwrap(){Err(error)=>assert_eq!(error.kind,ValueRefusalKind::AllocationFailed),Ok(_)=>panic!("constructor must refuse")}}let mut original=cursor.original.take().expect("failed constructor retains its original slot");assert_eq!(original.identity(),pointer);assert_eq!(original.get().0,42);assert_eq!(original.take_value().unwrap().0,42);assert!(original.terminal_is_empty());assert!(cursor.terminal_is_empty());}
}

#[test]
fn last_alias_election_requotes_original_work_after_a_peer_retires(){
 fn run<T:RetireOwned+Sync>(value:T){let source=SealedShared::admit(value,SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:SealedShared::<T>::birth_bytes(),maximum_depth:1,..Default::default()}).unwrap_or_else(|_|panic!("interleaving fixture birth")).0;let peer=source.try_duplicate(RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()}).unwrap().0;let pointer=source.identity();let mut cursor=Cursor{handle:source,pending:ManuallyDrop::new(None),original:None};let old=cursor.demands(4096).unwrap();assert_eq!(old,RetirementDemand{depth:1,..Default::default()});let barrier=std::sync::Arc::new(std::sync::Barrier::new(2));let peer_barrier=std::sync::Arc::clone(&barrier);let peer=std::thread::spawn(move||{let mut cursor=Cursor{handle:peer,pending:ManuallyDrop::new(None),original:None};peer_barrier.wait();let d=cursor.demands(4096).unwrap();let(result,heap)=observe(||cursor.step(grant(d)));assert!(matches!(result.unwrap(),RetirementStep::Progress(RetainedCloneProgress{copied_items:1,..})));assert_eq!(heap,(0,0));assert!(cursor.terminal_is_empty());});barrier.wait();peer.join().unwrap();let(result,heap)=observe(||cursor.step(grant(old)));assert!(matches!(result.unwrap(),RetirementStep::BudgetExhausted));assert_eq!(heap,(0,0));let(result,heap)=observe(||cursor.step_selected(grant(old),old));let RetirementStep::Progress(p)=result.unwrap()else{panic!("new original election is a separately paid structural event")};assert_eq!(p,RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!(heap,(0,0));let d=cursor.demands(4096).unwrap();assert!(!crate::retained_clone::retained_clone_grant_admits(grant(old),d));let mut original=cursor.original.take().unwrap();assert_eq!(original.identity(),pointer);drop(original.take_value().unwrap());assert!(original.terminal_is_empty());assert!(cursor.terminal_is_empty());}
 run(Payload{text:"native original".to_owned()});run(RefusingSharedPayload(42));
}
